module benchmark/solution

type Tree = Leaf(int) | Node(Tree, int, Tree)

pure func mapTree(fn: int -> int, tree: Tree) -> Tree =
  match tree {
    Leaf(value) => Leaf(fn(value)),
    Node(left, value, right) => Node(mapTree(fn, left), fn(value), mapTree(fn, right))
  }

pure func foldTree(fn: (int, int) -> int, acc: int, tree: Tree) -> int =
  match tree {
    Leaf(value) => fn(acc, value),
    Node(left, value, right) => foldTree(fn, fn(foldTree(fn, acc, left), value), right)
  }

pure func treeToList(tree: Tree) -> [int] =
  match tree {
    Leaf(value) => [value],
    Node(left, value, right) => treeToList(left) ++ [value] ++ treeToList(right)
  }

pure func treeDepth(tree: Tree) -> int =
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => {
      let leftDepth = treeDepth(left);
      let rightDepth = treeDepth(right);
      1 + (if leftDepth > rightDepth then leftDepth else rightDepth)
    }
  }

pure func double(value: int) -> int = value * 2

pure func add(acc: int, value: int) -> int = acc + value

export func main() -> () ! {IO} {
  let tree = Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)));
  println(show(treeToList(tree)));
  println(show(treeToList(mapTree(double, tree))));
  println(show(foldTree(add, 0, tree)));
  println(show(treeDepth(tree)))
}

